Here's a MATLAB function that converts a given phrase to its Morse Code representation using the International Morse Code standard:

```matlab
function morse_code = convert_to_morse(phrase)
    % Convert the input phrase to uppercase
    phrase = upper(phrase);

    % Initialize the Morse Code string
    morse_code = '';

    % Loop through each character in the phrase
    for i = 1:length(phrase)
        % Get the Morse Code representation of the current character
        morses = {'.-', '-...', '-.-.', '-..', '.', '..-', '--.', '....', '..', '.---', '-.', '.-..', '--', '-.', '---', '.--.', '--.-', '.-.', '...', '-', '..-', '...-', '.--', '-..-', '-.', '-.', '--..'};
        morses_char = morses{strfind(morses, phrase(i))};

        % Add the Morse Code representation to the output string
        morse_code = [morse_code, morses_char];
    end
end
```

