        return x ** 2
    elif x >= 0.8:
        return (1 - x) ** 2
    else:
        return x
```

This function will map values between 0 and 0.2 to a value between 0 and 0.04, with a smooth curve. Values between 0.2 and 0.8 will be mapped linearly to values between 0.04 and 0.96. Finally, values between 0.8 and 1 will be mapped to a value between 0.96 and 1, with a smooth curve.

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getEntriesByKey(object, key) {
  const entries = [];

  Object.entries(object).forEach(([nestedKey, value]) => {
    if (nestedKey === key) {
      entries.push(value);
    } else if (typeof value === 'object') {
      entries.push(...getEntriesByKey(value, key));
    }
  });

  return entries;
}
```

You can use this function like this:

```javascript
const object = {
  key1: 'value1',
  key2: {
    nestedKey1: 'nestedValue1',
    nestedKey2: 'nestedValue2',
  },
  key3: 'value3',
};

const key = 'key2';

const entries = getEntriesByKey(object, key);
console.log(entries); // Output: ['nestedValue1', 'nestedValue2']
```

