type StructDefinition struct {
	Name    string `json:"name"`
	Fields []Field `json:"fields"`
}

type Field struct {
	Name   string `json:"name"`
	Type   string `json:"type"`
	Schema *schema.Schema `json:"-"`
}

func main() {
	file := "example.go" // Replace with the name of your Go source file
	structName := "MyStruct" // Replace with the name of the struct you want to convert

	content, err := ioutil.ReadFile(file)
	if err != nil {
		log.Fatal(err)
	}

	var definitions []StructDefinition
	err = json.Unmarshal(content, &definitions)
	if err != nil {
		log.Fatal(err)
	}

	for _, definition := range definitions {
		if definition.Name == structName {
			fields := definition.Fields
			schemaDef := &schema.Schema{
				Name: structName,
				Fields: make([]schema.Field, len(fields)),
			}

			for i, field := range fields {
				fieldSchema := &schema.Field{
					Name:  field.Name,
					Type:  field.Type,
					Schema: field.Schema,
				}

				schemaDef.Fields[i] = *fieldSchema
			}

			avroSchema, err := avro.NewSchema(schemaDef)
			if err != nil {
				log.Fatal(err)
