Here's a MATLAB code that implements this model:

```matlab
% Define the population size and initial values for speed and stamina
population_size = 100;
speed = rand(population_size, 1); % Random initial speeds between 0 and 1
stamina = rand(population_size, 1); % Random initial stamina levels between 0 and 1

% Define the fitness function
fitness = @(speed, stamina) speed * stamina; % Fitness is proportional to speed and stamina

% Define the number of generations
num_generations = 100;

% Simulate the evolutionary process
for i = 1:num_generations
    % Calculate the mean fitness of the population
    mean_fitness = mean(fitness(speed, stamina));

    % Select parents based on their fitness
    selected_parents = zeros(population_size, 2);
    for j = 1:population_size
        selected_parents(j, :) = [speed(j), stamina(j)];
        [~, idx] = sort(fitness(selected_parents(j, :)), 'descend');
        selected_parents(j, :) = selected_parents(idx(1), :);
    end

    % Create offspring by combining the genes of the selected parents
    offspring = zeros(population_size, 2);
    for j = 1:population_size
        offspring(j, 1) = (selected_parents(j, 1) + selected_parents(j, 2)) / 2;
        offspring(j, 2) = (selected_parents(j, 1) + selected_parents(j, 2)) / 2;
    end

    % Update the population with the offspring
    speed = offspring(:, 1);

