#include <stdio.h>
#include <stdlib.h>

char *argv_to_cstring(int argc, char **argv) {
    int i;
    char *cstring = malloc(sizeof(char) * (argc + 1));
    for (i = 0; i < argc; i++) {
        strcat(cstring, argv[i]);
        if (i != argc - 1) {
            strcat(cstring, " ");
        }
    }
    cstring[argc] = '\0';
    return cstring;
}

int main() {
    int argc = 3;
    char **argv = {"hello", "world", "!"};
    char *cstring = argv_to_cstring(argc, argv);
    printf("%s\n", cstring);
    free(cstring);
    return 0;
}
```

