Here's a simple example of a toast notification using React Context:

```jsx
import React, { createContext, useContext } from 'react';

const ToastContext = createContext(null);

function ToastProvider({ children }) {
  const [toast, setToast] = React.useState(null);

  function showToast(message) {
    setToast({ message, visible: true });
  }

  function hideToast() {
    setToast({ ...toast, visible: false });
  }

  return (
    <ToastContext.Provider value={{ showToast, hideToast }}>
      {children}
    </ToastContext.Provider>
  );
}

function ToastConsumer() {
  const { showToast, hideToast } = useContext(ToastContext);

  return (
    <div>
      {toast && (
        <div className="toast">
          <p>{toast.message}</p>
          <button onClick={hideToast}>Close</button>
        </div>
      )}
    </div>
  );
}

export default function App() {
  return (
    <ToastProvider>
      <ToastConsumer />
    </ToastProvider>
  );
}
```

In this example, we have a `ToastContext` that provides a `showToast` and `hideToast` function to the child components. The `ToastConsumer` component consumes the context and renders the toast message when it's available.

