// Function to calculate the product of the prime numbers
function calculateProduct() {
    const primeNumbers = [3, 7, 13, 19];
    let product = 1;

    for (let i = 0; i < primeNumbers.length; i++) {
        product *= primeNumbers[i];
    }

    return product;
}

// Call the function and display the result
const product = calculateProduct();
document.getElementById("product").innerHTML = `The product of the prime numbers is ${product}.`;
