```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Accord.MachineLearning.Text;
using Accord.MachineLearning.Utilities;

namespace TextClassification
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the dataset
            var dataset = new List<Sentence>();
            var filePath = Path.Combine("dataset", "text_dataset.csv");
            using (var reader = new StreamReader(filePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    var parts = line.Split(',');
                    var sentence = new Sentence
                    {
                        Text = parts[0],
                        Category = parts[1]
                    };
                    dataset.Add(sentence);
                }
            }

            // Preprocess the data
            var vectorizer = new CountVectorizer();
            var transformedData = vectorizer.Transform(dataset);

            // Train the Naive Bayes classifier
            var naiveBayes = new NaiveBayes();
            naiveBayes.Fit(transformedData);

            // Predict the labels of new observations
            var newObservations = new List<Sentence>
            {
