                new Sentence { Text = "The political rally was intense.", Category = "Politics" },
                new Sentence { Text = "The entertainment show was amazing.", Category = "Entertainment" }
            };
            var predictions = naiveBayes.Predict(newObservations);

            // Print the predictions
            foreach (var prediction in predictions)
            {
                Console.WriteLine($"Predicted category: {prediction}");
            }
        }
    }

