Here's a Go function that checks if a given sentence contains a double negative:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	doubleNegative := containsDoubleNegative(sentence)
	if doubleNegative {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func containsDoubleNegative(sentence string) bool {
	negativeWords := []string{"not", "never", "rarely", "seldom", "hardly"}
	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && containsNotFollowedByNegativeWord(word, words) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, negativeWord := range negativeWords {
		if word == negativeWord || word == "-" + negativeWord {
			return true
		}
	}
	return false
}

func containsNotFollowedByNegativeWord(word string, words []string) bool {
	for _, nextWord := range words {
		if nextWord == "not" && containsNegativeWord(nextWord) {
			return true
		}
	}
	return false
}
```

This code defines two helper functions `containsNegativeWord` and `containsNotFollowedByNegativeWord`. The `containsDoubleNegative` function uses these helper functions to check if the given sentence contains a double negative. It iterates through each word in the sentence, checking if it is a negative word and if it is followed by the word "not" and another negative word. If both conditions are met, the function returns true, indicating that the sentence contains a double negative. Otherwise, it returns false.

